const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
(async()=>{
 let lib;
 for(const entry of process.env.PATH.split(path.delimiter)){const candidate=path.resolve(entry,'../firebase-tools/lib');if(fs.existsSync(path.join(candidate,'requireAuth.js'))){lib=candidate;break}}
 assert.ok(lib);
 const account='phuckk2101@gmail.com',project='bepxinh-b0be7',options={project,account,nonInteractive:true};
 const auth=require(path.join(lib,'auth'));auth.setActiveAccount(options,auth.selectAccount(account,process.cwd()));assert.equal(options.user.email,account);
 await require(path.join(lib,'requireAuth')).requireAuth(options);
 const {Client}=require(path.join(lib,'apiv2')),api=new Client({urlPrefix:'https://firebaserules.googleapis.com',auth:true});
 const release=(await api.get(`/v1/projects/${project}/releases/cloud.firestore`)).body;
 const ruleset=(await api.get(`/v1/${release.rulesetName}`)).body;
 const normalize=s=>s.replace(/\r\n/g,'\n');
 const remote=normalize(ruleset.source.files.find(f=>f.name==='firestore.rules').content),local=normalize(fs.readFileSync('firestore.rules','utf8'));
 const reviewed=remote.replace(".hasOnly(['name', 'bio', 'showBio', 'updatedAt']);",".hasOnly(['name', 'bio', 'showBio', 'avatarUrl', 'updatedAt']);");
 const openDefault="rules_version = '2'; service cloud.firestore { match /databases/{database}/documents { match /{document=**} { allow read, write: if true; } } }";
 if(remote.replace(/\s+/g,'')===openDefault.replace(/\s+/g,'')) {
   assert.equal(local,normalize(fs.readFileSync('build/firestore.rules','utf8')),'Deploy source must match emulator-tested rules');
   console.log('PASS: identified fully open live rules; restoring emulator-tested scoped rules plus owner avatar support');
 } else {
   assert.equal(local,reviewed,'Local rules contain changes beyond reviewed avatar allowance');
   console.log('PASS: only reviewed owner avatar update allowance differs from live rules');
 }
})().catch(e=>{console.error(e.message);process.exitCode=1});
